--
-- Table structure for table `candidato_suplentes`
--

DROP TABLE IF EXISTS `candidato_suplentes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `candidato_suplentes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `candidato_id` int(10) unsigned NOT NULL,
  `ordem` tinyint(4) NOT NULL COMMENT '1 para 1º Suplente, 2 para 2º Suplente',
  `nome_completo` varchar(255) NOT NULL,
  `nome_urna` varchar(150) DEFAULT NULL,
  `partido` varchar(50) DEFAULT NULL,
  `numero_urna` varchar(10) DEFAULT NULL,
  `situacao_registro` varchar(100) NOT NULL DEFAULT 'Deferido',
  `foto_url` varchar(255) DEFAULT NULL,
  `cpf_mascarado` varchar(20) DEFAULT NULL,
  `ocupacao` varchar(150) DEFAULT NULL,
  `total_bens` decimal(15,2) NOT NULL DEFAULT 0.00,
  `processo_tse` varchar(100) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `candidato_id_ordem` (`candidato_id`,`ordem`),
  CONSTRAINT `candidato_suplentes_candidato_id_foreign` FOREIGN KEY (`candidato_id`) REFERENCES `candidatos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=648 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

